export function blobPath(ctx, x, y, rx, ry, rot, seed, wob = .1) {
  const n = 26;
  const pts = [];
  for (let i = 0; i < n; i++) {
    const a = (i / n) * TAU;
    const r = 1 + Math.sin(a * 3 + seed) * wob + Math.sin(a * 5 + seed * 1.7) * wob * .55 + Math.sin(a * 7 + seed * .6) * wob * .3;
    const px = Math.cos(a) * rx * r, py = Math.sin(a) * ry * r;
    const c = Math.cos(rot), s = Math.sin(rot);
    pts.push([x + px * c - py * s, y + px * s + py * c]);
  }
  ctx.beginPath();
  // midpoint smoothing
  const mid = (p, q) => [(p[0]+q[0])/2, (p[1]+q[1])/2];
  let m = mid(pts[n-1], pts[0]);
  ctx.moveTo(m[0], m[1]);
  for (let i=0;i<n;i++){
    const p=pts[i], q=pts[(i+1)%n], m2=mid(p,q);
    ctx.quadraticCurveTo(p[0],p[1],m2[0],m2[1]);
  }
  ctx.closePath();
}
