+    c.vy *= Math.exp(-dt * 5);
+    if (c.recoverT <= 0) c.state = 'idle';
+  }
+
+  c.x += c.vx * dt;
+  c.y += c.vy * dt;
+  c.x = clamp(c.x, 5480, WORLD_W - 40);
+  c.y = clamp(c.y, 80, WORLD_H - 80);
+
+  const face = c.state === 'lunge' ? Math.atan2(c.vy, c.vx) : Math.atan2(dy, dx);
