+  const nx = (target.x - p.x) / (dist(p.x, p.y, target.x, target.y) || 1);
+  const ny = (target.y - p.y) / (dist(p.x, p.y, target.x, target.y) || 1);
+  target.kvx += nx * (target.boss ? 60 : 170);
+  target.kvy += ny * (target.boss ? 60 : 170);
