  ctx.fillStyle = baseGrad;
  ctx.fillRect(0, 0, w, h);

  // large wet washes
  for (let i = 0; i < 46; i++) {
    const x = rnd() * w, y = rnd() * h;
    const rx = between(rnd, 140, 430), ry = between(rnd, 90, 330);
    softBlob(ctx, x, y, rx, ry, pick(rnd, P.washes), between(rnd, 0.035, 0.09), between(rnd, -0.5, 0.5));
  }
  // sunlight / light pools
  const lights = zone.palette === 'deep' ? 12 : 18;
  for (let i = 0; i < lights; i++) {
    softBlob(ctx, rnd() * w, rnd() * h, between(rnd, 70, 240), between(rnd, 60, 200), P.light, between(rnd, 0.04, 0.1));
  }
  // damp blooms — pigment rings
  for (let i = 0; i < 22; i++) {
    const x = rnd() * w, y = rnd() * h, r = between(rnd, 24, 85);
    for (let k = 0; k < 3; k++) {
      inkContour(ctx, x, y, r * (0.7 + k * 0.18), r * (0.62 + k * 0.17), P.ink, between(rnd, 0.018, 0.05), between(rnd, 0.7, 2.4), between(rnd, -0.4, 0.4), rnd() * 10 + k, 0.2);
    }
  }

  // — the walk
  const steps = Math.ceil(w / 26);
  for (let i = 0; i <= steps; i++) {
    const x = (i / steps) * w;
    const py = pathY(absX(x));
    softBlob(ctx, x, py, 88, 170, P.path, 0.055);
  }
  for (let i = 0; i <= steps; i += 1) {
    const x = (i / steps) * w;
    const py = pathY(absX(x));
    softBlob(ctx, x + between(rnd, -6, 6), py + between(rnd, -20, 20), 36, 105, mixHex(P.path, P.paper, 0.25), 0.05);
  }
  // scattered dry brush on the walk
  for (let i = 0; i < 260; i++) {
    const x = rnd() * w;
    const y = pathY(absX(x)) + between(rnd, -125, 125);
    ctx.fillStyle = hexA(mixHex(P.path, P.ink, 0.25), between(rnd, 0.02, 0.09));
    ctx.beginPath();
    ctx.ellipse(x, y, between(rnd, 0.6, 3.4), between(rnd, 0.4, 1.4), between(rnd, -1, 1), 0, TAU);
    ctx.fill();
  }

  // little pebbles on the walk
  const pebbles = zone.palette === 'garden' ? 30 : 18;
  for (let i = 0; i < pebbles; i++) {
