76: export function blobPath(ctx, x, y, rx, ry, rot = 0, seed = 1, wob = 0.1) {
77:   const n = 24;
78:   const pts = [];
79:   const c = Math.cos(rot), s = Math.sin(rot);
80:   for (let i = 0; i < n; i++) {
81:     const a = (i / n) * TAU;
82:     const r = 1
83:       + Math.sin(a * 3 + seed) * wob
84:       + Math.sin(a * 5 + seed * 1.7) * wob * 0.55
85:       + Math.sin(a * 7 + seed * 0.6) * wob * 0.3;
86:     const px = Math.cos(a) * rx * r;
87:     const py = Math.sin(a) * ry * r;
88:     pts.push([x + px * c - py * s, y + px * s + py * c]);
89:   }
90:   ctx.beginPath();
91:   const mx = (pts[n - 1][0] + pts[0][0]) / 2;
92:   const my = (pts[n - 1][1] + pts[0][1]) / 2;
93:   ctx.moveTo(mx, my);
94:   for (let i = 0; i < n; i++) {
95:     const p = pts[i];
96:     const q = pts[(i + 1) % n];
97:     ctx.quadraticCurveTo(p[0], p[1], (p[0] + q[0]) / 2, (p[1] + q[1]) / 2);
98:   }
99:   ctx.closePath();
100: }
