102: export function washEllipse(ctx, x, y, rx, ry, color, alpha, rot = 0, seed = 1, wob = 0.08) {
103:   ctx.save();
104:   blobPath(ctx, x, y, rx, ry, rot, seed, wob);
105:   ctx.fillStyle = hexA(color, alpha);
106:   ctx.fill();
107:   if (alpha > 0.08) {
108:     blobPath(ctx, x + rx * 0.06, y - ry * 0.08, rx * 0.8, ry * 0.79, rot, seed + 2, wob * 1.2);
109:     ctx.fillStyle = hexA(color, alpha * 0.45);
110:     ctx.fill();
111:   }
112:   ctx.restore();
113: }
