115: export function inkContour(ctx, x, y, rx, ry, color, alpha = 0.4, lw = 1, rot = 0, seed = 1, wob = 0.1) {
116:   blobPath(ctx, x, y, rx, ry, rot, seed, wob);
117:   ctx.strokeStyle = hexA(color, alpha);
118:   ctx.lineWidth = lw;
119:   ctx.lineCap = 'round';
120:   ctx.stroke();
