123: export function brushCurve(ctx, x1, y1, cx, cy, x2, y2, color, alpha, lw) {
124:   ctx.beginPath();
125:   ctx.moveTo(x1, y1);
126:   ctx.quadraticCurveTo(cx, cy, x2, y2);
127:   ctx.strokeStyle = hexA(color, alpha);
128:   ctx.lineWidth = lw;
129:   ctx.lineCap = 'round';
130:   ctx.stroke();
131: }
