133: export function splatter(ctx, x, y, r, color, alpha, rnd, count = 12) {
134:   for (let i = 0; i < count; i++) {
135:     const a = rnd() * TAU;
136:     const d = Math.pow(rnd(), 0.6) * r;
137:     const size = between(rnd, 0.4, 2.6) * (1 - d / (r * 1.4));
138:     ctx.fillStyle = hexA(color, alpha * between(rnd, 0.35, 1));
139:     ctx.beginPath();
140:     ctx.arc(x + Math.cos(a) * d, y + Math.sin(a) * d, Math.max(0.3, size), 0, TAU);
141:     ctx.fill();
142:   }
143: }
