145: export function paperGrain(ctx, w, h, rnd, count = 6000) {
146:   for (let i = 0; i < count; i++) {
147:     const x = rnd() * w, y = rnd() * h;
148:     const light = rnd() > 0.55;
149:     ctx.fillStyle = light
150:       ? `rgba(255,252,240,${between(rnd, 0.02, 0.15)})`
151:       : `rgba(80,78,52,${between(rnd, 0.015, 0.075)})`;
152:     const s = between(rnd, 0.3, 1.4);
153:     ctx.fillRect(x, y, s, s);
154:   }
155:   // a few darker granules
156:   for (let i = 0; i < count * 0.08; i++) {
157:     ctx.fillStyle = `rgba(66,68,46,${between(rnd, 0.03, 0.1)})`;
158:     ctx.beginPath();
159:     ctx.arc(rnd() * w, rnd() * h, between(rnd, 0.4, 1.1), 0, TAU);
160:     ctx.fill();
161:   }
162: }
