164: function grassTuft(ctx, x, y, h, color, ink, alpha, rnd) {
165:   const blades = 2 + ((rnd() * 4) | 0);
166:   for (let b = 0; b < blades; b++) {
167:     const lean = between(rnd, -0.75, 0.75) * h;
168:     const bh = h * between(rnd, 0.55, 1);
169:     const cx = x + lean * 0.25;
170:     const cy = y - bh * 0.55;
171:     const tx = x + lean;
172:     const ty = y - bh;
173:     ctx.beginPath();
174:     ctx.moveTo(x + between(rnd, -1.5, 1.5), y);
175:     ctx.quadraticCurveTo(cx, cy, tx, ty);
176:     ctx.strokeStyle = hexA(color, alpha * between(rnd, 0.45, 1));
177:     ctx.lineWidth = between(rnd, 0.55, 1.5);
178:     ctx.lineCap = 'round';
179:     ctx.stroke();
180:   }
181:   if (rnd() > 0.82) {
182:     ctx.fillStyle = hexA(ink, alpha * 0.45);
183:     ctx.beginPath();
184:     ctx.ellipse(x, y - h * 0.35, 0.8, 2.4, 0.4, 0, TAU);
185:     ctx.fill();
186:   }
187: }
