189: export function daisy(ctx, x, y, r, petal, heart, ink, alpha, rnd, petals = 7) {
190:   softBlob(ctx, x, y, r * 2.4, r * 2.2, petal, alpha * 0.13);
191:   const rot = rnd() * TAU;
192:   ctx.save();
193:   ctx.translate(x, y);
194:   ctx.rotate(rot);
195:   for (let i = 0; i < petals; i++) {
196:     const a = (i / petals) * TAU;
197:     ctx.save();
198:     ctx.rotate(a);
199:     ctx.beginPath();
200:     ctx.ellipse(r * 0.62, 0, r * 0.58, r * 0.25, 0, 0, TAU);
201:     ctx.fillStyle = hexA(petal, alpha * between(rnd, 0.55, 0.9));
202:     ctx.fill();
203:     ctx.restore();
204:   }
205:   ctx.beginPath();
206:   ctx.arc(0, 0, r * 0.3, 0, TAU);
207:   ctx.fillStyle = hexA(heart, alpha * 1.15);
208:   ctx.fill();
209:   ctx.strokeStyle = hexA(ink, alpha * 0.4);
210:   ctx.lineWidth = 0.6;
211:   ctx.stroke();
212:   ctx.restore();
