244:     brushCurve(ctx, tx, ty, tx + Math.cos(a) * len * 0.6, ty + Math.sin(a) * len * 0.6, tx + Math.cos(a) * len, ty + Math.sin(a) * len, color, alpha * 0.5, 0.7);
