252: function clover(ctx, x, y, r, color, alpha, rnd) {
253:   ctx.save();
254:   ctx.translate(x, y);
255:   ctx.rotate(rnd() * TAU);
256:   for (let i = 0; i < 3; i++) {
257:     ctx.save();
258:     ctx.rotate((i / 3) * TAU);
259:     ctx.beginPath();
260:     ctx.ellipse(r * 0.55, 0, r * 0.5, r * 0.34, 0, 0, TAU);
261:     ctx.fillStyle = hexA(color, alpha * 0.65);
262:     ctx.fill();
263:     ctx.restore();
264:   }
