268: function fern(ctx, x, y, size, color, ink, alpha, rnd) {
269:   const fronds = 4 + ((rnd() * 3) | 0);
270:   for (let f = 0; f < fronds; f++) {
271:     const baseA = -Math.PI / 2 + (f / fronds - 0.5) * 2.1 + between(rnd, -0.15, 0.15);
272:     const len = size * between(rnd, 0.65, 1.05);
273:     const ex = x + Math.cos(baseA) * len;
274:     const ey = y + Math.sin(baseA) * len;
275:     const cx = x + Math.cos(baseA) * len * 0.5 + between(rnd, -8, 8);
276:     const cy = y + Math.sin(baseA) * len * 0.5;
277:     brushCurve(ctx, x, y, cx, cy, ex, ey, ink, alpha * 0.55, 0.9);
278:     const steps = 7;
279:     for (let i = 1; i <= steps; i++) {
280:       const t = i / steps;
281:       const mx = lerp(x, ex, t) + Math.sin(t * 3) * 2;
282:       const my = lerp(y, ey, t);
283:       const ll = size * 0.15 * (1 - t * 0.6);
284:       for (const side of [-1, 1]) {
285:         const a = baseA + side * 1.05;
286:         brushCurve(ctx, mx, my, mx + Math.cos(a) * ll * 0.5, my + Math.sin(a) * ll * 0.5, mx + Math.cos(a) * ll, my + Math.sin(a) * ll, color, alpha * 0.5, 0.75);
287:       }
288:     }
289:   }
290: }
