292: function mushroom(ctx, x, y, r, capColor, stemColor, ink, alpha, rnd, spots = 3) {
293:   const stemH = r * between(rnd, 0.9, 1.5);
294:   ctx.beginPath();
295:   ctx.moveTo(x - r * 0.16, y);
296:   ctx.quadraticCurveTo(x - r * 0.12, y - stemH * 0.5, x - r * 0.18, y - stemH);
297:   ctx.lineTo(x + r * 0.18, y - stemH);
298:   ctx.quadraticCurveTo(x + r * 0.12, y - stemH * 0.5, x + r * 0.16, y);
299:   ctx.closePath();
300:   ctx.fillStyle = hexA(stemColor, alpha * 0.8);
301:   ctx.fill();
302:   ctx.strokeStyle = hexA(ink, alpha * 0.3);
303:   ctx.lineWidth = 0.6;
304:   ctx.stroke();
305: 
306:   ctx.save();
307:   ctx.translate(x, y - stemH);
308:   ctx.beginPath();
309:   ctx.ellipse(0, 0, r * 0.95, r * 0.5, 0, Math.PI, TAU);
310:   ctx.lineTo(-r * 0.95, 0);
311:   ctx.closePath();
312:   ctx.fillStyle = hexA(capColor, alpha * 0.82);
313:   ctx.fill();
314:   ctx.strokeStyle = hexA(ink, alpha * 0.35);
315:   ctx.lineWidth = 0.7;
316:   ctx.stroke();
317:   for (let i = 0; i < spots; i++) {
318:     ctx.beginPath();
319:     ctx.arc(between(rnd, -r * 0.55, r * 0.55), between(rnd, -r * 0.34, -r * 0.08), between(rnd, 0.6, 1.8), 0, TAU);
320:     ctx.fillStyle = hexA('#f8f0da', alpha * 0.75);
321:     ctx.fill();
322:   }
323:   ctx.restore();
324: }
