335: export function giantLeaf(ctx, x, y, r, rot, color, ink, alpha, rnd) {
336:   softBlob(ctx, x, y, r * 1.1, r * 0.9, color, alpha * 0.16, rot);
337:   ctx.save();
338:   ctx.translate(x, y);
339:   ctx.rotate(rot);
340:   ctx.beginPath();
341:   ctx.moveTo(0, 0);
342:   ctx.quadraticCurveTo(r * 0.55, -r * 0.62, r, 0);
343:   ctx.quadraticCurveTo(r * 0.55, r * 0.62, 0, 0);
344:   ctx.fillStyle = hexA(color, alpha * 0.55);
345:   ctx.fill();
346:   ctx.strokeStyle = hexA(ink, alpha * 0.4);
347:   ctx.lineWidth = 0.9;
348:   ctx.stroke();
349:   ctx.beginPath();
350:   ctx.moveTo(0, 0);
351:   ctx.quadraticCurveTo(r * 0.5, r * 0.06, r * 0.97, 0);
352:   ctx.strokeStyle = hexA(ink, alpha * 0.35);
353:   ctx.lineWidth = 0.8;
354:   ctx.stroke();
355:   for (let i = 1; i < 5; i++) {
