357:     for (const side of [-1, 1]) {
358:       ctx.beginPath();
359:       ctx.moveTo(r * t * 0.9, 0);
360:       ctx.quadraticCurveTo(r * (t + 0.06) * 0.9, side * r * 0.22, r * (t + 0.1), side * r * 0.35 * (1 - t * 0.4));
361:       ctx.strokeStyle = hexA(ink, alpha * 0.22);
362:       ctx.lineWidth = 0.55;
363:       ctx.stroke();
364:     }
365:   }
366:   ctx.restore();
