418: export function paintZoneCanvas(zone) {
419:   const S = 0.8;
420:   const w = zone.x1 - zone.x0;
421:   const h = 1800;
422:   const cv = document.createElement('canvas');
423:   cv.width = Math.round(w * S);
424:   cv.height = Math.round(h * S);
425:   const ctx = cv.getContext('2d');
426:   ctx.scale(S, S);
427:   const P = PALETTES[zone.palette];
428:   const rnd = mulberry32(zone.x0 * 7 + zone.index * 991 + 17);
429:   const absX = (x) => zone.x0 + x;
430: 
431:   // — base paper
432:   ctx.fillStyle = P.paper;
433:   ctx.fillRect(0, 0, w, h);
434: 
435:   // broad first wash, slightly darker at the edges of the world
436:   const baseGrad = ctx.createLinearGradient(0, 0, 0, h);
437:   baseGrad.addColorStop(0, hexA(P.washes[0], 0.10));
438:   baseGrad.addColorStop(0.45, hexA(P.washes[2], 0.05));
439:   baseGrad.addColorStop(1, hexA(P.washes[5] || P.washes[0], 0.12));
440:   ctx.fillStyle = baseGrad;
441:   ctx.fillRect(0, 0, w, h);
442: 
443:   // large wet washes
444:   for (let i = 0; i < 60; i++) {
445:     const x = rnd() * w, y = rnd() * h;
446:     const rx = between(rnd, 140, 430), ry = between(rnd, 90, 330);
447:     softBlob(ctx, x, y, rx, ry, pick(rnd, P.washes), between(rnd, 0.05, 0.13), between(rnd, -0.5, 0.5));
448:   }
449:   // broad undergrowth shadow
450:   for (let i = 0; i < 20; i++) {
451:     softBlob(ctx, rnd() * w, rnd() * h, between(rnd, 90, 260), between(rnd, 60, 200), mixHex(P.washes[2], P.ink, 0.3), between(rnd, 0.04, 0.09));
452:   }
453:   // sunlight / light pools
454:   const lights = zone.palette === 'deep' ? 12 : 20;
455:   for (let i = 0; i < lights; i++) {
456:     softBlob(ctx, rnd() * w, rnd() * h, between(rnd, 70, 240), between(rnd, 60, 200), P.light, between(rnd, 0.06, 0.14));
457:   }
458:   // damp blooms — pigment rings
459:   for (let i = 0; i < 24; i++) {
460:     const x = rnd() * w, y = rnd() * h, r = between(rnd, 24, 85);
461:     for (let k = 0; k < 3; k++) {
462:       inkContour(ctx, x, y, r * (0.7 + k * 0.18), r * (0.62 + k * 0.17), P.ink, between(rnd, 0.02, 0.06), between(rnd, 0.7, 2.4), between(rnd, -0.4, 0.4), rnd() * 10 + k, 0.2);
463:     }
464:   }
465:   // leafy clumps give the ground some body
466:   for (let i = 0; i < 55; i++) {
467:     const x = rnd() * w;
468:     const y = rnd() * h;
469:     if (Math.abs(y - pathY(absX(x))) < 130 && rnd() < 0.7) continue;
470:     foliageClump(ctx, x, y, between(rnd, 26, 74), pick(rnd, P.washes), P.ink, between(rnd, 0.10, 0.22), rnd);
471:   }
472: 
473:   // — the walk
474:   const steps = Math.ceil(w / 26);
475:   for (let i = 0; i <= steps; i++) {
476:     const x = (i / steps) * w;
477:     const py = pathY(absX(x));
478:     softBlob(ctx, x, py, 92, 176, P.path, 0.09);
479:   }
480:   for (let i = 0; i <= steps; i += 1) {
481:     const x = (i / steps) * w;
482:     const py = pathY(absX(x));
483:     softBlob(ctx, x + between(rnd, -6, 6), py + between(rnd, -20, 20), 40, 110, mixHex(P.path, P.paper, 0.25), 0.075);
484:   }
485:   // scattered dry brush on the walk
486:   for (let i = 0; i < 380; i++) {
487:     const x = rnd() * w;
488:     const y = pathY(absX(x)) + between(rnd, -125, 125);
489:     ctx.fillStyle = hexA(mixHex(P.path, P.ink, 0.25), between(rnd, 0.03, 0.12));
490:     ctx.beginPath();
491:     ctx.ellipse(x, y, between(rnd, 0.6, 3.4), between(rnd, 0.4, 1.4), between(rnd, -1, 1), 0, TAU);
492:     ctx.fill();
493:   }
494: 
495:   // little pebbles on the walk
496:   const pebbles = zone.palette === 'garden' ? 34 : 20;
497:   for (let i = 0; i < pebbles; i++) {
498:     const x = rnd() * w;
499:     const y = pathY(absX(x)) + between(rnd, -100, 100);
500:     washEllipse(ctx, x, y, between(rnd, 2, 7), between(rnd, 1.4, 4), mixHex(P.path, '#8d8970', 0.35), 0.45, rnd() * TAU, rnd() * 9, 0.16);
501:   }
502: 
503:   // — grass field
504:   const grassCount = zone.palette === 'meadow' ? 4400 : zone.palette === 'deep' ? 3200 : 3700;
505:   for (let i = 0; i < grassCount; i++) {
506:     const x = rnd() * w;
507:     const y = rnd() * h;
508:     const d = Math.abs(y - pathY(absX(x)));
509:     if (d < 55 && rnd() < 0.82) continue;
510:     if (d < 135 && rnd() < 0.38) continue;
